              ["10–15 kPa", ("Suggestive of cACLD", "يشير إلى مرض متقدّم معاوَض")],
              [">15 kPa", ("Highly suggestive of cACLD", "يشير بقوة إلى مرض متقدّم معاوَض")],
              [("≤15 kPa + platelets ≥150", "≤15 + صفائح ≥150"), ("Rules out clinically significant portal hypertension (CSPH)", "ينفي ارتفاع ضغط الوريد البابي المهم سريريًا")],
              [("<20 kPa + platelets >150", "<20 + صفائح >150"), ("Screening endoscopy for varices can be skipped", "يمكن الاستغناء عن منظار الكشف عن الدوالي")],
